-- Modera receives separate native1/1 and3/3 messages two seconds apart.
-- Keep DATA_SET3/3 independent; do not execute it from the first facing change.
SET @modera_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
SET @modera_smart_scripts=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`id` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`link` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_z` AS CHAR CHARACT