SET @modera_old=@modera_smart_scripts='246fa7f408e9026970440a68b7c2e4349b45af58aed31b6651baaa1513c32066';
SET @modera_applied=@modera_smart_scripts='762319e7d3c65c1f775b0530795fc4362e0608a8e814bc7481060ea1b5791ec5';
SET @modera_safe=(@modera_old OR @modera_applied) AND @modera_conditions='327728e6ec9a5c200ac8bec58c1f661ccc5d94c4528a920eeb0b2c53cd456524' AND @modera_gossip_menu_option='847c9e445a19e8b7c9d82a7e5ff0f7e516cfae490d18a509c532301d78fa7d18' AND @modera_creature_template='9ee8772de8c1fb68e8eadf963a37b7feefe57ac2676601000b9335b7c37f1c0c';
